<?php require "db.php"; $rows=$conn->query("SELECT flight_id, flight_name, route, departure_date, total_seats, seats_available, created_at FROM flights ORDER BY flight_id DESC"); ?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Flight List</title><link rel="stylesheet" href="style.css"></head><body><?php require "header.php"; ?><main class="container">
<div class="page-head"><div class="eyebrow">Database Records</div><h1>Flight List</h1><p>These records are read directly from the FLY Air MySQL database in XAMPP.</p></div>
<div class="panel panel-dark"><div class="table-wrap"><table class="table"><tr><th>Flight Id</th><th>Flight Name</th><th>Route</th><th>Departure Date</th><th>Total Seats</th><th>Seats Available</th><th>Created At</th></tr><?php while($r=$rows->fetch_assoc()): ?><tr><td><?=e($r['flight_id'])?></td><td><?=e($r['flight_name'])?></td><td><?=e($r['route'])?></td><td><?=e($r['departure_date'])?></td><td><?=e($r['total_seats'])?></td><td><?=e($r['seats_available'])?></td><td><?=e($r['created_at'])?></td></tr><?php endwhile;?></table></div></div>
</main><?php require "footer.php"; ?></body></html>